package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.*;import android.media.ThumbnailUtils;import android.net.Uri;import android.os.Bundle;import android.provider.*;import android.view.*;import android.widget.*;import androidx.activity.OnBackPressedCallback;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.core.content.FileProvider;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.io.*;import java.text.*;import java.util.*;import java.util.concurrent.*;

public class PrivateMediaActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final ArrayList<JSONObject> items=new ArrayList<>();private PrivateHubRepository repo;private LinearLayout list;private TextView count;private String requestedMime;
 private final ActivityResultLauncher<String> picker=registerForActivityResult(new ActivityResultContracts.GetContent(),this::picked);
 private final ActivityResultLauncher<Intent> galleryPicker=registerForActivityResult(new ActivityResultContracts.StartActivityForResult(),result->{if(result.getResultCode()==RESULT_OK&&result.getData()!=null)picked(result.getData().getData());});
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){goHome();}});repo=new PrivateHubRepository(this);preparePreviewDirectory();build();load();}
 private void build(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Ui.BG);ScrollView scroll=new ScrollView(this);LinearLayout page=Ui.column(this);page.setPadding(Ui.dp(this,20),Ui.dp(this,14),Ui.dp(this,20),Ui.dp(this,100));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView back=Ui.text(this,"‹",40,Ui.NAVY);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->goHome());bar.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,54)));ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.ic_private_media);bar.addView(icon,new LinearLayout.LayoutParams(Ui.dp(this,52),Ui.dp(this,52)));LinearLayout names=Ui.column(this);names.setPadding(Ui.dp(this,12),0,0,0);TextView title=Ui.title(this,"Media",25);title.setTextColor(Ui.NAVY);names.addView(title);count=Ui.text(this,"Opening Private Media…",13,Ui.MUTED);names.addView(count);bar.addView(names,new LinearLayout.LayoutParams(0,-2,1));page.addView(bar);TextView notice=Ui.text(this,"Encrypted photos, videos, and voice notes are stored in My Vault's private app space. Vault copies are not added to Gallery or Photos.",14,Ui.MUTED);notice.setLineSpacing(0,1.15f);notice.setPadding(Ui.dp(this,4),Ui.dp(this,18),Ui.dp(this,4),Ui.dp(this,16));page.addView(notice);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);actions.addView(action("▧\nPhoto","image/*"),actionParams(0));actions.addView(action("▶\nVideo","video/*"),actionParams(8));actions.addView(action("◉\nVoice Note","audio/*"),actionParams(8));page.addView(actions);TextView label=Ui.title(this,"Private Media",18);label.setTextColor(Ui.NAVY);label.setPadding(Ui.dp(this,4),Ui.dp(this,22),0,Ui.dp(this,10));page.addView(label);list=Ui.column(this);page.addView(list);scroll.addView(page);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));setContentView(root);}
 private TextView action(String name,String mime){TextView button=Ui.text(this,name,13,Color.WHITE);button.setTypeface(null,android.graphics.Typeface.BOLD);button.setGravity(Gravity.CENTER);button.setBackground(Ui.bg(Ui.TEAL,Ui.dp(this,18)));button.setOnClickListener(v->{requestedMime=mime;if("image/*".equals(mime))openGallery();else picker.launch(mime);});return button;}
 private void openGallery(){Intent intent=new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI).setType("image/*");Intent samsung=new Intent(intent).setPackage("com.sec.android.gallery3d");galleryPicker.launch(samsung.resolveActivity(getPackageManager())!=null?samsung:intent);}
 private LinearLayout.LayoutParams actionParams(int left){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,66),1);p.leftMargin=Ui.dp(this,left);return p;}
 private void picked(Uri uri){if(uri==null)return;String mime=getContentResolver().getType(uri);if(mime==null)mime=requestedMime==null?"application/octet-stream":requestedMime.replace("*","octet-stream");String defaultName=displayName(uri);LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,5),Ui.dp(this,18),0);EditText title=Ui.field(this,"Media name",false);title.setText(stripExtension(defaultName));box.addView(title,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));String selectedMime=mime;AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Save To Private Media").setMessage("My Vault will encrypt a private copy on this phone.").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Encrypt & Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isEmpty()){title.setError("Give this media a name");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{repo.addMedia(name,selectedMime,uri);runOnUiThread(()->{dialog.dismiss();load();Ui.toast(this,"Media Encrypted And Saved");});}catch(Exception error){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);Ui.toast(this,"Could Not Save This Media");});}});}));dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void load(){io.execute(()->{try{JSONArray data=repo.media();items.clear();for(int i=data.length()-1;i>=0;i--)items.add(data.getJSONObject(i));runOnUiThread(this::render);}catch(Exception error){runOnUiThread(()->Ui.toast(this,"Could Not Open Private Media"));}});}
 private void render(){list.removeAllViews();count.setText(items.size()+" Private Item"+(items.size()==1?"":"s"));if(items.isEmpty()){TextView empty=Ui.text(this,"No private media saved yet. Choose Photo, Video, or Voice Note to encrypt your first item.",15,Ui.MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(Ui.dp(this,24),Ui.dp(this,42),Ui.dp(this,24),Ui.dp(this,42));empty.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,18)));list.addView(empty);return;}for(JSONObject item:items){View row=mediaBubble(item);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Ui.dp(this,94));p.leftMargin=Ui.dp(this,22);p.bottomMargin=Ui.dp(this,10);list.addView(row,p);}}
 private View mediaBubble(JSONObject item){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(this,9),Ui.dp(this,9),Ui.dp(this,13),Ui.dp(this,9));row.setBackground(Ui.stroke(Ui.SOFT,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,18)));FrameLayout preview=new FrameLayout(this);preview.setBackground(Ui.bg(Ui.ACCENT_DARK,Ui.dp(this,14)));ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.addView(image,new FrameLayout.LayoutParams(-1,-1));TextView type=Ui.text(this,symbol(item.optString("mime")),25,Color.WHITE);type.setGravity(Gravity.CENTER);preview.addView(type,new FrameLayout.LayoutParams(-1,-1));row.addView(preview,new LinearLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,72)));LinearLayout words=Ui.column(this);words.setPadding(Ui.dp(this,13),0,0,0);TextView title=Ui.title(this,item.optString("title","Private Media"),16);title.setTextColor(Ui.INK);words.addView(title);String date=new SimpleDateFormat("dd/MM/yy · h:mm a",Locale.getDefault()).format(new Date(item.optLong("createdAt")));words.addView(Ui.text(this,kind(item.optString("mime"))+"  ·  "+date,12,Ui.MUTED));TextView status=Ui.text(this,"🔒 Encrypted In My Vault",11,0xff0b8179);status.setPadding(0,Ui.dp(this,5),0,0);words.addView(status);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));row.setOnClickListener(v->open(item));row.setOnLongClickListener(v->{options(item);return true;});if(item.optString("mime").startsWith("image/"))io.execute(()->{try{byte[] raw=repo.mediaBytes(item);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=4;Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length,options);runOnUiThread(()->{if(bitmap!=null){type.setVisibility(View.GONE);image.setImageBitmap(bitmap);}});}catch(Exception ignored){}});return row;}
 private void open(JSONObject item){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Opening Secure Media…");wait.show();io.execute(()->{try{File file=repo.openMedia(item,previewDir());Uri uri=FileProvider.getUriForFile(this,getPackageName()+".files",file);Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,item.optString("mime","application/octet-stream")).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);runOnUiThread(()->{wait.dismiss();try{startActivity(Intent.createChooser(view,"Open Private Media"));}catch(Exception error){Ui.toast(this,"No App Can Open This Media Type");}});}catch(Exception error){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Decrypt This Media");});}});}
 private void options(JSONObject item){new AlertDialog.Builder(this).setTitle(item.optString("title")).setItems(new String[]{"Open","Delete"},(d,which)->{if(which==0)open(item);else new AlertDialog.Builder(this).setTitle("Delete Private Media?").setMessage("This permanently removes the encrypted vault copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,w)->io.execute(()->{try{repo.deleteMedia(item.optString("id"));runOnUiThread(this::load);}catch(Exception error){runOnUiThread(()->Ui.toast(this,"Could Not Delete This Media"));}})).show();}).show();}
 private String displayName(Uri uri){try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())return cursor.getString(0);}catch(Exception ignored){}return "Private Media";}
 private String stripExtension(String value){int dot=value.lastIndexOf('.');return dot>0?value.substring(0,dot):value;}
 private String symbol(String mime){return mime.startsWith("video/")?"▶":mime.startsWith("audio/")?"🎙":"▧";}
 private String kind(String mime){return mime.startsWith("video/")?"Video":mime.startsWith("audio/")?"Voice Note":"Photo";}
 private File previewDir(){return new File(getCacheDir(),"exports/private_media");}
 private void preparePreviewDirectory(){File directory=previewDir();if(!directory.exists())directory.mkdirs();File[] files=directory.listFiles();if(files!=null)for(File file:files)if(!".nomedia".equals(file.getName()))file.delete();try{new File(directory,".nomedia").createNewFile();}catch(Exception ignored){}}
 private void goHome(){startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
